export const DICTS = { fr, en, de };
let lang = 'fr';

export function initLang() {
  const saved = safeStorage.get(CONFIG.langKey);
  const nav = (navigator.language || 'fr').slice(0, 2);
  lang = CONFIG.languages.includes(saved) ? saved : (CONFIG.languages.includes(nav) ? nav : 'fr');
  document.documentElement.lang = lang;
  return lang;
}
export const getLang = () => lang;
export function setLang(l) {
  if (!CONFIG.languages.includes(l)) return;
  lang = l;
  safeStorage.set(CONFIG.langKey, l);
  document.documentElement.lang = l;
}

/** Traduit une clé, avec remplacement de {variables}. Repli sur le français. */
export function t(key, vars) {
  let s = DICTS[lang][key] ?? DICTS.fr[key];
  if (s === undefined) { console.warn(`[i18n] clé manquante : ${key}`); return key; }
  if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? `{${k}}`));
  return s;
}
/** Pluriel simple (_one / _other). */
export const tp = (key, n, vars = {}) => t(`${key}_${Number(n) === 1 ? 'one' : 'other'}`, { n, ...vars });

/** Applique les traductions aux attributs data-i18n* d'une zone. */
export function applyI18n(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); }); // contenu de confiance (dictionnaire)
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll('[data-i18n-aria]').forEach((el) => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
}
